mapper.select:
SELECT id::text,goal_id::text,event_type,before_status,after_status,before_archived,after_archived,
    name_snapshot,entity_version,occurred_at,source_type,created_at
FROM goal_state_history WHERE user_id=#{userId} AND goal_id=#{id}
ORDER BY occurred_at DESC,id DESC LIMIT #{size} OFFSET #{offset}
